/* skill cloud (fixed bottom of viewport; horizontal layout) */
#skill-area { position: fixed !important; left: 50%; transform: translateX(-50%); bottom: 8vh; width: calc(100% - 48px); max-width: 64rem; z-index: 60; pointer-events: auto; display: flex; justify-content: center; }
#skill-cloud { position:relative; pointer-events: auto; display: flex; justify-content: center; gap: 8px; flex-wrap: nowrap; }
/* each skill - horizontal positioning with proper spacing */
/* hidden by default — revealed by the sequence (class .show) */
#skill-cloud .skill { position:relative; opacity:0; font-weight:700; font-size:15px; padding:10px 14px; margin:0; border-radius:8px; user-select:none; cursor:pointer; transition: transform 0.36s cubic-bezier(.2,.9,.3,1), opacity 0.22s ease, color 0.12s ease, box-shadow 0.36s ease; pointer-events:none; white-space:nowrap; }
/* invisible expansion around each skill to make hover less precise */
#skill-cloud .skill::after{ content:''; position:absolute; inset:-8px; border-radius:10px; pointer-events:none; }
#skill-cloud .skill.show, #skill-cloud .skill:hover, #skill-cloud .skill:focus, #skill-cloud .skill.active { transform: translateY(-4px) scale(1.08); opacity:1; z-index:999; box-shadow: 0 10px 30px rgba(0,0,0,0.16); pointer-events:auto; }

