// --- SKILL CLOUD: sequence-on-hover (sliding window, multiple skills) ---
(function(){
  var skills = ["Cloud","DevSecOps","Security","Infrastructure","CI/CD","Automation","SRE","Observability","Compliance","Kubernetes","Terraform","Monitoring"];
  var container = document.getElementById('skill-cloud'); if(!container) return;
  var hint = document.querySelector('.skill-hint');
  var els = [];

  function render(){
    els = [];
    container.innerHTML = '';
    skills.forEach(function(s){
      var el = document.createElement('span'); el.className = 'skill'; el.tabIndex = -1; el.setAttribute('role','img'); el.setAttribute('aria-label', s);
      el.textContent = s;
      container.appendChild(el);
      els.push(el);
    });
  }

  render(); window.addEventListener('resize', function(){ render(); });

  // sequence controls - show 5 skills at a time
  var seqTimer = null; var seqIndex = 0; var windowSize = 5; var intervalMs = 1200;
  function showWindow(start){
    els.forEach(function(el){ el.classList.remove('show'); el.style.zIndex = 1; el.setAttribute('aria-hidden','true'); el.tabIndex = -1; });
    for(var k=0;k<windowSize;k++){
      var idx = (start + k) % els.length; var el = els[idx]; if(!el) continue;
      el.classList.add('show'); el.style.zIndex = 100 + k; el.setAttribute('aria-hidden','false'); el.tabIndex = 0;
    }
  }
  function startSequence(){ if(seqTimer) return; seqIndex = 0; showWindow(seqIndex); seqTimer = setInterval(function(){ seqIndex = (seqIndex + 1) % els.length; showWindow(seqIndex); }, intervalMs); }
  function stopSequence(){ if(seqTimer){ clearInterval(seqTimer); seqTimer = null; } els.forEach(function(el){ el.classList.remove('show'); el.style.zIndex = 1; el.setAttribute('aria-hidden','true'); el.tabIndex = -1; }); }

  // hide initially
  stopSequence();

  // trigger on container and hint (ensure hint accepts pointer events)
  container.addEventListener('mouseenter', startSequence);
  container.addEventListener('mouseleave', stopSequence);
  container.addEventListener('focusin', startSequence);
  container.addEventListener('focusout', stopSequence);
  if(hint){
    hint.style.pointerEvents = 'auto';
    hint.addEventListener('mouseenter', startSequence);
    hint.addEventListener('mouseleave', stopSequence);
    hint.addEventListener('focus', startSequence);
    hint.addEventListener('blur', stopSequence);
  }
})();

