       stopSequence();

       // trigger on container and hint (ensure hint accepts pointer events)
       container.addEventListener('mouseenter', startSequence);
       container.addEventListener('mouseleave', stopSequence);
       container.addEventListener('focusin', startSequence);
       container.addEventListener('focusout', stopSequence);
       if(hint){
         hint.style.pointerEvents = 'auto';
         hint.addEventListener('mouseenter', startSequence);
         hint.addEventListener('mouseleave', stopSequence);
         hint.addEventListener('focus', startSequence);
         hint.addEventListener('blur', stopSequence);
       }
     })();

