var seqTimer = null; var seqIndex = 0; var windowSize = 3; var intervalMs = 1200;
function showWindow(start){
  // calculate positions for centered layout
  var visibleEls = [];
  for(var k=0;k<windowSize;k++){
    var idx = (start + k) % els.length;
    visibleEls.push(els[idx]);
  }
  // hide all first
  els.forEach(function(el){ el.classList.remove('show'); el.style.zIndex = 1; el.setAttribute('aria-hidden','true'); el.tabIndex = -1; el.style.left='50%'; el.style.transform='translateX(-50%)'; });
  // position visible ones centered with gap
  var totalWidth = 0;
  var widths = visibleEls.map(function(el){ return el.offsetWidth; });
  for(var i=0;i<widths.length;i++) totalWidth += widths[i];
  totalWidth += (visibleEls.length - 1) * 10; // gap
  var startX = -totalWidth / 2;
  for(var j=0;j<visibleEls.length;j++){
    var el = visibleEls[j];
    el.style.left = '50%';
    el.style.transform = 'translateX(calc(-50% + ' + (startX + widths[j]/2) + 'px))';
    el.classList.add('show');
    el.style.zIndex = 100 + j;
    el.setAttribute('aria-hidden','false');
    el.tabIndex = 0;
    startX += widths[j] + 10;
  }
}

