    // smooth anchor scrolling
    document.querySelectorAll('a[href^="#"]').forEach(function(a){ a.addEventListener('click', function(e){ var t=document.querySelector(this.getAttribute('href')); if(t){ e.preventDefault(); t.scrollIntoView({behavior:'smooth', block:'start'}); } }); });

    // --- SKILL CLOUD: sequence-on-hover (sliding window, multiple skills) ---
    (function(){
      var skills = ["Cloud","DevSecOps","Security","Infrastructure","CI/CD","Automation","SRE","Observability","Compliance","Kubernetes","Terraform","Monitoring"];
      var container = document.getElementById('skill-cloud'); if(!container) return;
      var hint = document.querySelector('.skill-hint');
      var els = [];

      function render(){
        els = [];
        container.innerHTML = '';
        skills.forEach(function(s){
          var el = document.createElement('span'); el.className = 'skill'; el.tabIndex = -1; el.setAttribute('role','img'); el.setAttribute('aria-label', s);
          el.textContent = s;
          container.appendChild(el);
          els.push(el);
        });
      }

      render(); window.addEventListener('resize', function(){ render(); showWindow(seqIndex); });

      // sequence controls - show 3 skills at a time, centered
      var seqTimer = null; var seqIndex = 0; var windowSize = 3; var intervalMs = 1200;
      function showWindow(start){
        // calculate positions for centered layout
        var visibleEls = [];
        for(var k=0;k<windowSize;k++){
          var idx = (start + k) % els.length;
          visibleEls.push(els[idx]);
        }
        // hide all first
        els.forEach(function(el){ el.classList.remove('show'); el.style.zIndex = 1; el.setAttribute('aria-hidden','true'); el.tabIndex = -1; el.style.left='50%'; el.style.transform='translateX(-50%)'; });
        // position visible ones centered with gap
        var totalWidth = 0;
        var widths = visibleEls.map(function(el){ return el.offsetWidth; });
        for(var i=0;i<widths.length;i++) totalWidth += widths[i];
        totalWidth += (visibleEls.length - 1) * 10; // gap
        var startX = -totalWidth / 2;
        for(var j=0;j<visibleEls.length;j++){
          var el = visibleEls[j];
          el.style.left = '50%';
          el.style.transform = 'translateX(calc(-50% + ' + (startX + widths[j]/2) + 'px))';
          el.classList.add('show');
          el.style.zIndex = 100 + j;
          el.setAttribute('aria-hidden','false');
          el.tabIndex = 0;
          startX += widths[j] + 10;
        }
      }
      function startSequence(){ if(seqTimer) return; seqIndex = 0; showWindow(seqIndex); seqTimer = setInterval(function(){ seqIndex = (seqIndex + 1) % els.length; showWindow(seqIndex); }, intervalMs); }
      function stopSequence(){ if(seqTimer){ clearInterval(seqTimer); seqTimer = null; } els.forEach(function(el){ el.classList.remove('show'); el.style.zIndex = 1; el.setAttribute('aria-hidden','true'); el.tabIndex = -1; }); }

      // hide initially
      stopSequence();

      // trigger on container and hint (ensure hint accepts pointer events)
      container.addEventListener('mouseenter', function(){ showWindow(seqIndex); startSequence(); });
      container.addEventListener('mouseleave', stopSequence);
      container.addEventListener('focusin', function(){ showWindow(seqIndex); startSequence(); });
      container.addEventListener('focusout', stopSequence);
      if(hint){
        hint.style.pointerEvents = 'auto';
        hint.addEventListener('mouseenter', startSequence);
        hint.addEventListener('mouseleave', stopSequence);
        hint.addEventListener('focus', startSequence);
        hint.addEventListener('blur', stopSequence);
      }
    })();

  </script>
</body>
</html>

