         <svg class="sound-on" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 010 7.07M19.07 4.93a9 9 0 010 14.14"/></svg>
       </button>
       <button id="theme-toggle" aria-pressed="false" title="Toggle theme (system/light/dark)" class="icon-button ml-2" aria-label="Toggle theme">
         <svg class="theme-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M1 12h2M21 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"/></svg>
         <span class="theme-label">System</span>
       </button>
     </nav>
   </header>

   <main class="hero-wrap px-6 text-center">
     <div>
       <h1 id="hero" class="text-5xl sm:text-7xl md:text-9xl leading-tight" aria-label="Amarbir Singh">Amarbir<br class="sm:hidden"> Singh</h1>
