     @media (max-width: 640px) {
       #hero .char.space { width:100%; height:0; display:block; }
     }
     /* tilt classes: alternate char tilts left/right on hover */
     #hero .char.tilt-left { transform: rotate(-18deg) translateY(6px) scale(.99); opacity:.95; }
     #hero .char.tilt-right { transform: rotate(18deg) translateY(6px) scale(.99); opacity:.95; }

     /* layout tweaks */
     header { background: transparent; font-family: ui-monospace, 'Cascadia Code', 'Source Code Pro', Menlo, Consolas, monospace; }
     nav a, nav button { color: var(--muted); }
