     }

     /* scroll hint */
     .scroll-hint { position:absolute; bottom:40px; left:50%; transform:translateX(-50%); color:var(--muted); opacity:0.6; animation:bounce 2s infinite; }
     .scroll-hint:hover { opacity:1; }
     @keyframes bounce { 0%,100%{ transform:translateX(-50%) translateY(0); } 50%{ transform:translateX(-50%) translateY(8px); } }
   </style>
 </head>
