+(function(){
+  var meta = document.querySelector('meta[name="github-issue"]');
+  var issue = meta && meta.getAttribute('content');
+  if(!issue) return;
+
+  var repo = 'a-5ingh/singhamarbir.com';
+  var apiUrl = 'https://api.github.com/repos/' + repo + '/issues/' + issue;
