// Redirect to GitHub OAuth authorization
export async function onRequestGet(context) {
  const { request, env } = context;
  const url = new URL(request.url);
  const redirect = url.searchParams.get('redirect') || '/blogs/';
  const state = crypto.randomUUID();

  const githubUrl = new URL('https://github.com/login/oauth/authorize');
  githubUrl.searchParams.set('client_id', env.GITHUB_CLIENT_ID);
  githubUrl.searchParams.set('redirect_uri', `${url.origin}/api/auth`);
  githubUrl.searchParams.set('scope', 'public_repo');
  githubUrl.searchParams.set('state', state);
  githubUrl.searchParams.set('allow_signup', 'true');

  const headers = new Headers();
  headers.append('Location', githubUrl.toString());
  headers.append('Set-Cookie', `gh_state=${state}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=600`);

  return new Response(null, { status: 302, headers });
}

// Handle GitHub OAuth callback
export async function onRequestGet(context) {
  const { request, env } = context;
  const url = new URL(request.url);
  const code = url.searchParams.get('code');
  const state = url.searchParams.get('state');
  const redirect = url.searchParams.get('redirect') || '/blogs/';

  const cookieHeader = request.headers.get('Cookie') || '';
  const stateMatch = cookieHeader.match(/gh_state=([^;]+)/);
  const savedState = stateMatch ? stateMatch[1] : '';

  if (!code || !state || state !== savedState) {
    return new Response('Invalid or missing OAuth state', { status: 400 });
  }

  const tokenRes = await fetch('https://github.com/login/oauth/access_token', {
    method: 'POST',
    headers: {
      'Accept': 'application/json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      client_id: env.GITHUB_CLIENT_ID,
      client_secret: env.GITHUB_CLIENT_SECRET,
      code
    })
  });

  const tokenData = await tokenRes.json();
  if (!tokenData.access_token) {
    return new Response('GitHub authentication failed', { status: 400 });
  }

  const headers = new Headers();
  headers.append('Location', redirect);
  headers.append('Set-Cookie', `gh_token=${tokenData.access_token}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=604800`);
  headers.append('Set-Cookie', 'gh_state=; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=0');

  return new Response(null, { status: 302, headers });
}

// Check current GitHub auth status
export async function onRequestGet(context) {
  const { request, env } = context;
  const cookieHeader = request.headers.get('Cookie') || '';
  const tokenMatch = cookieHeader.match(/gh_token=([^;]+)/);

  if (!tokenMatch) {
    return json({ authed: false });
  }

  const token = tokenMatch[1];
  const res = await fetch('https://api.github.com/user', {
    headers: {
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/vnd.github+json'
    }
  });

  if (!res.ok) {
    return json({ authed: false });
  }

  const user = await res.json();
  return json({ authed: true, user: user.login, avatar: user.avatar_url });
}

function json(data) {
  return new Response(JSON.stringify(data), { headers: { 'Content-Type': 'application/json' } });
}

// Post a heart reaction to a GitHub issue
export async function onRequestPost(context) {
  const { request, env } = context;
  const cookieHeader = request.headers.get('Cookie') || '';
  const tokenMatch = cookieHeader.match(/gh_token=([^;]+)/);

  if (!tokenMatch) {
    return new Response('Unauthorized', { status: 401 });
  }

  const token = tokenMatch[1];
  const body = await request.json();
  const issue = body.issue;
  if (!issue) {
    return new Response('Missing issue number', { status: 400 });
  }

  const res = await fetch(`https://api.github.com/repos/a-5ingh/singhamarbir.com/issues/${issue}/reactions`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/vnd.github.squirrel-girl-preview+json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ content: 'heart' })
  });

  if (!res.ok) {
    const err = await res.text();
    return new Response(err, { status: res.status });
  }

  const data = await res.json();
  return new Response(JSON.stringify(data), { headers: { 'Content-Type': 'application/json' } });
}

// Post a comment to a GitHub issue
export async function onRequestPost(context) {
  const { request, env } = context;
  const cookieHeader = request.headers.get('Cookie') || '';
  const tokenMatch = cookieHeader.match(/gh_token=([^;]+)/);

  if (!tokenMatch) {
    return new Response('Unauthorized', { status: 401 });
  }

  const token = tokenMatch[1];
  const body = await request.json();
  const issue = body.issue;
  const text = body.text;
  if (!issue || !text || !text.trim()) {
    return new Response('Missing issue or comment text', { status: 400 });
  }

  const res = await fetch(`https://api.github.com/repos/a-5ingh/singhamarbir.com/issues/${issue}/comments`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ body: text.trim() })
  });

  if (!res.ok) {
    const err = await res.text();
    return new Response(err, { status: res.status });
  }

  const data = await res.json();
  return new Response(JSON.stringify(data), { headers: { 'Content-Type': 'application/json' } });
}

