         return r.text().then(function(text){
           console.log('[engagement] error body:', text);
           var msg = text;
           try { var parsed = JSON.parse(text); if(parsed.error) msg = parsed.error; } catch(e){}
           throw new Error(msg || ('HTTP ' + r.status));
         });
       }
